// CloudtainerML rev0030 — Confidence-adaptive SwiGLU / MoE activation probe.
// Tiny performance-cost screen inspired by confidence-adaptive MoE activations.
#include <bits/stdc++.h>
using namespace std; static string q(const string&s){string o="\""; for(char c:s){if(c=='\"'||c=='\\')o+='\\'; if(c=='\n')o+="\\n"; else o+=c;} return o+'\"';}
struct Regime{string name; double confidence, ambiguity, rare_expert, nonlinear_need, overconfidence, load_skew;};
struct Row{string regime,method; int experts,tokens; double quality,cost_frac,route_flip,rare_miss,load_penalty,regret,score;};
static double C(double x){return max(0.0,min(1.0,x));}
static Row eval(const Regime&r,string m,int E,int T){double quality=0,cost=0,flip=0,rare=0,load=0; double logE=log2(E+1.0);
 if(m=="dense_swiglu"){quality=.96-.04*r.ambiguity; cost=1.0; load=.02;}
 else if(m=="standard_top2_moe"){quality=C(.74+.16*r.confidence+.10*r.nonlinear_need-.22*r.ambiguity-.16*r.overconfidence); cost=.30+.04*logE; flip=.14*r.ambiguity+.20*r.overconfidence; rare=.26*r.rare_expert; load=.26*r.load_skew;}
 else if(m=="confidence_adaptive_swiglu"){quality=C(.72+.18*r.confidence+.18*r.nonlinear_need-.12*r.ambiguity-.14*r.overconfidence); cost=.24+.05*logE+.12*(1-r.confidence); flip=.10*r.ambiguity+.16*r.overconfidence; rare=.18*r.rare_expert; load=.18*r.load_skew;}
 else if(m=="confidence_plus_rare_guard"){quality=C(.70+.15*r.confidence+.18*r.nonlinear_need+.14*r.rare_expert-.12*r.ambiguity-.10*r.overconfidence); cost=.29+.05*logE+.10*r.rare_expert; flip=.09*r.ambiguity+.10*r.overconfidence; rare=.07*r.rare_expert; load=.20*r.load_skew;}
 else if(m=="always_tiny_linear_experts"){quality=C(.56+.22*r.confidence-.18*r.nonlinear_need-.24*r.ambiguity-.12*r.rare_expert); cost=.15+.03*logE; flip=.18*r.ambiguity; rare=.40*r.rare_expert; load=.22*r.load_skew;}
 else { // hpo_switch_dense_or_adaptive
   bool hard = r.ambiguity+r.overconfidence+r.rare_expert>1.25 || r.nonlinear_need>.75; Row a=eval(r, hard?"dense_swiglu":"confidence_adaptive_swiglu", E,T); a.method=m; a.cost_frac += .035; a.score=0; return a; }
 double need=.72+.18*r.nonlinear_need+.10*r.rare_expert; double err=max(0.0,need-quality); double score=err+.18*cost+.22*flip+.24*rare+.14*load; return {r.name,m,E,T,quality,cost,flip,rare,load,0,score};}
int main(int argc,char**argv){string outp=argc>1?argv[1]:"REV0030_CONFIDENCE_ADAPTIVE_SWIGLU_SMOKE.json"; vector<Regime> regs={{"easy_high_confidence",.95,.08,.08,.25,.05,.20},{"ambiguous_boundary",.45,.82,.22,.45,.35,.35},{"rare_expert_needed",.60,.30,.92,.62,.20,.55},{"overconfident_wrong",.88,.55,.45,.55,.92,.50},{"nonlinear_dense_need",.58,.42,.36,.94,.22,.30},{"load_skewed_moe",.70,.28,.30,.45,.18,.92}}; vector<string> ms={"dense_swiglu","standard_top2_moe","confidence_adaptive_swiglu","confidence_plus_rare_guard","always_tiny_linear_experts","hpo_switch_dense_or_adaptive"}; vector<Row> rows; map<string,int>w,non; for(auto&r:regs) for(int E:{16,64,128}) for(int T:{256,2048,8192}){vector<Row> cand; for(auto&m:ms){auto x=eval(r,m,E,T); double need=.72+.18*r.nonlinear_need+.10*r.rare_expert; double err=max(0.0,need-x.quality); x.score=err+.18*x.cost_frac+.22*x.route_flip+.24*x.rare_miss+.14*x.load_penalty; cand.push_back(x);} double best=1e9; for(auto&x:cand)best=min(best,x.score); for(auto&x:cand){x.regret=max(0.0,x.score-best); rows.push_back(x);} auto b=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); w[b->method]++; auto nb=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="dense_swiglu")return false; if(b.method=="dense_swiglu")return true; return a.score<b.score;}); non[nb->method]++;}
 ofstream f(outp); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0030\",\n  \"probe\": \"confidence_adaptive_swiglu\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:w){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:non){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"Confidence-adaptive MoE activations look useful when confidence is informative, but rare-expert and overconfident-wrong regimes need guards or dense fallback.\",\n    \"screen_regret_fields\": [\"quality\",\"cost_frac\",\"route_flip\",\"rare_miss\",\"load_penalty\",\"regret\",\"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"experts\": "<<r.experts<<", \"tokens\": "<<r.tokens<<", \"quality\": "<<r.quality<<", \"cost_frac\": "<<r.cost_frac<<", \"route_flip\": "<<r.route_flip<<", \"rare_miss\": "<<r.rare_miss<<", \"load_penalty\": "<<r.load_penalty<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1<rows.size()?",":"")<<"\n";} f<<"  ]\n}\n";}
